    LoanPage getActiveLoans(GetMemberLoansQuery query);

    record GetMemberLoansQuery(UUID memberId, int page, int size) {

        public static final int MAX_PAGE_SIZE = 100;

        public GetMemberLoansQuery {
            if (memberId == null) {
                throw new IllegalArgumentException("memberId is required");
            }
            if (page < 0) {
                throw new IllegalArgumentException("page must not be negative");
            }
            if (size < 1 || size > MAX_PAGE_SIZE) {
                throw new IllegalArgumentException("size must be between 1 and " + MAX_PAGE_SIZE);
            }
        }
    }

    record ActiveLoan(UUID loanId, UUID bookId, String title, LocalDate loanedAt, LocalDate dueAt) {
    }

    record LoanPage(List<ActiveLoan> items, int page, int size, long totalCount) {
    }
}

